#!/bin/sh
# First start of the bundle's database: the extensions and the application
# role (no BYPASSRLS: row-level security backs every tenant predicate). Its
# password is generated by the gateway (hex, so it needs no quoting).
set -eu
psql -v ON_ERROR_STOP=1 --username postgres --dbname notification <<SQL
CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE ROLE notification_app LOGIN PASSWORD '${NOTIFICATION_APP_PASSWORD}' NOBYPASSRLS;
GRANT CONNECT ON DATABASE notification TO notification_app;
SQL
